from collections import defaultdict
from dataclasses import dataclass
from enum import Enum

from typing import List, Tuple, Mapping

LABEL_POSITIVE = True
LABEL_NEGATIVE = False
BINARY_LABELS = frozenset({LABEL_NEGATIVE, LABEL_POSITIVE})


@dataclass
class TextElement:
    uri: str
    text: str
    span: List[Tuple]
    metadata: Mapping
    category_to_label: defaultdict # TODO does this still need to be a defaultdict?

    @classmethod
    def get_field_names(cls):
        return cls.__annotations__.keys()


@dataclass
class Document:
    uri: str
    text_elements: List[TextElement]
    metadata: Mapping


class LabelType(Enum):
    Standard = ""
    Weak = "Weak"


@dataclass
class Label:
    label: bool
    metadata: Mapping
    label_type: LabelType

    def __init__(self, label: bool, metadata=None, label_type: LabelType = LabelType.Standard):

        if metadata is None:
            metadata = {}
        self.label = label
        self.metadata = metadata
        self.label_type = label_type

    def get_detailed_label_name(self):
        return str(self.label) if self.label_type == LabelType.Standard else f'{self.label_type.name}_{self.label}'

    def to_dict(self):
        dict_for_json = {'label': self.label, 'metadata': self.metadata} # TODO this means label_type is not saved
        return dict_for_json


class DisplayFields(object):
    workspace_id = 'workspace_id'
    category_name = 'category_name'
    doc_id = 'doc_id'
    dataset = 'dataset'
    text = 'text'
    uri = 'uri'
    element_metadata = 'element_metadata'
    label = 'label'
    label_metadata = 'label_metadata'
    label_type = 'label_type'

